@dataclass
class Repeat:
    interval: int = 1
    unit: str = 'D'
    until: object = None
    weekdays: list = field(default_factory=list)
    months: list = field(default_factory=list)
    monthdays: list = field(default_factory=list)
    exceptions: list = field(default_factory=list)

    def raw(self):
        s = '{' + str(self.interval) + self.unit
        if self.until:
            s += ' -> ' + native_date(self.until)
        for key, values in [('w', self.weekdays), ('m', self.months), ('d', self.monthdays)]:
            s += ''.join(' ' + key + str(x) for x in sorted(values))
        s += ''.join(' !' + native_date(x) for x in sorted(self.exceptions))
        return s + '}'

    def matches(self, start, d, exceptions=True):
        if isinstance(start, datetime):
            start = start.date()
        if d < start or (self.until and d > self.until):
            return False
        if exceptions and d in self.exceptions:
            return False
        n = self.interval
        if n <= 0:
            return False
        u = self.unit
        if u == 'D':
            if (d-start).days % n:
                return False
        elif u == 'W':
            # Repetition weeks are anchored to Monday, as in RFC5545.
            a = start - timedelta(days=start.weekday())
            b = d - timedelta(days=d.weekday())
            if ((b-a).days//7) % n:
                return False
            if not self.weekdays and d.weekday() != start.weekday():
                return False
        elif u == 'M':
            if ((d.year-start.year)*12 + d.month-start.month) % n:
                return False
            if not self.weekdays and not self.monthdays and d.day != start.day:
                return False
        elif u == 'Y':
            if (d.year-start.year) % n:
                return False
            if not self.months and not self.weekdays and not self.monthdays and d.month != start.month:
                return False
            if not self.weekdays and not self.monthdays and d.day != start.day:
                return False
        if self.months and d.month not in self.months:
            return False
        if self.monthdays:
            last = calendar.monthrange(d.year,d.month)[1]
            if not any(d.day == (x if x > 0 else last + x + 1) for x in self.monthdays):
                return False
        if self.weekdays:
            found = False
            for x in self.weekdays:
                wd = abs(x) % 7
                ordinal = (abs(x)//7) * (-1 if x < 0 else 1)
                if weekday(d) != wd:
                    continue
                if not ordinal:
                    found = True
