NDATE = r'([+-]?\d+)\s*/\s*([+-]?\d+)\s*/\s*([+-]?\d+)'

def parse_native_date(s):
    m = re.fullmatch(NDATE,s.strip())
    if not m:
        raise ValueError('syntax error in the item date')
    try:
        return date(int(m[3]),int(m[1]),int(m[2]))
    except (ValueError, OverflowError):
        raise ValueError('date error in event')

def parse_repeat(s):
    m = re.match(r'\s*(\d+)([DWMY])',s)
    if not m:
        raise ValueError('syntax error in the repetition')
    r = Repeat(int(m[1]),m[2]); tail=s[m.end():].strip()
    if tail.startswith('->'):
        m = re.match(r'->\s*' + NDATE,tail)
        if not m:
            raise ValueError('syntax error in the repetition')
        r.until=date(int(m[3]),int(m[1]),int(m[2])); tail=tail[m.end():]
    while tail.strip():
        tail=tail.lstrip()
        m=re.match(r'([wmd])([+-]?\d+)',tail)
        if m:
            {'w':r.weekdays,'m':r.months,'d':r.monthdays}[m[1]].append(int(m[2]));tail=tail[m.end():];continue
        m=re.match('!'+NDATE,tail)
        if m:
            r.exceptions.append(date(int(m[3]),int(m[1]),int(m[2])));tail=tail[m.end():];continue
        raise ValueError('syntax error in the repetition')
    return r

def parse_item(s, kind):
    if kind == 'todo':
        p=9;done=False
        if s.startswith('['):
            m=re.match(r'\[(-?\d+)\]',s)
            if not m:
                raise ValueError('syntax error in item identifier')
            done=m[1].startswith('-');p=abs(int(m[1]));s=s[m.end():]
        note=None
        if s.startswith('>'):
            m=re.match(r'>(\S+)\s?',s)
            if not m:
                raise ValueError('syntax error in note name')
            note=m[1];s=s[m.end():]
        elif s.startswith(' '):
            s=s[1:]
        return Item('todo',s,priority=p,completed=done,note=note)
    m=re.match(NDATE,s)
    if not m:
        raise ValueError('syntax error in the item date')
    try:
        d=date(int(m[3]),int(m[1]),int(m[2]))
    except (ValueError,OverflowError):
        raise ValueError('date error in event')
    tail=s[m.end():].lstrip()
    if tail.startswith('@'):
        m=re.match(r'@\s*(\d+)\s*:\s*(\d+)\s*->\s*'+NDATE+r'\s*@\s*(\d+)\s*:\s*(\d+)',tail)
        if not m:
            raise ValueError('syntax error in appointment')
        try:
            start=datetime(d.year,d.month,d.day,int(m[1]),int(m[2]))
            end=datetime(int(m[5]),int(m[3]),int(m[4]),int(m[6]),int(m[7]))
            duration=epoch(end)-epoch(start)
            if duration<0:raise ValueError()
        except (ValueError,OverflowError):
            raise ValueError('date error in appointment')
        item=Item('apt',start=start,duration=duration)
    else:
        m=re.match(r'\[([+-]?\d+)\]\s?',tail)
        if not m:
            raise ValueError('syntax error in item identifier')
        item=Item('event',start=midnight(d),ident=int(m[1]))
    tail=tail[m.end():].lstrip()
    if tail.startswith('{'):
        k=tail.find('}')
        if k<0:raise ValueError('syntax error in the repetition')
        item.repeat=parse_repeat(tail[1:k]);tail=tail[k+1:].lstrip()
    if tail.startswith('>'):
        m=re.match(r'>(\S+)\s?',tail)
        if not m:raise ValueError('syntax error in note name')
        item.note=m[1];tail=tail[m.end():]
    if item.kind=='apt':
        if not tail or tail[0] not in '|!':
            raise ValueError('syntax error in appointment state')
        item.flagged=tail[0]=='!';tail=tail[1:]
    item.message=tail
    return item

