GREP_ORDER=['todo','recur-event','recur-apt','apt','event']
EXPORT_ORDER=['recur-event','event','recur-apt','apt','todo']
SAVE_ORDER=['recur-event','recur-apt','apt','event']

def ordered(items, order=GREP_ORDER):
    return sorted(items,key=lambda it:(order.index(it.type),it.sortkey()))

def save_items(items, apts, todos):
    write_text(apts,''.join(i.raw()+'\n' for i in ordered([x for x in items if x.kind!='todo'],SAVE_ORDER)))
    write_text(todos,''.join(i.raw()+'\n' for i in sorted([x for x in items if x.kind=='todo'],key=lambda i:i.sortkey())))

def truncdiv(n,d):
    return int(n/d)

def duration_format(n,fmt):
    if fmt=='epoch':return str(n)
    if fmt=='default':fmt='%EH:%M'
    out='';i=0
    while i<len(fmt):
        c=fmt[i];i+=1
        if c!='%':out+=c;continue
        pad=True;extended=False
        if i<len(fmt) and fmt[i]=='-':pad=False;i+=1
        if i<len(fmt) and fmt[i]=='E':extended=True;i+=1
        if i>=len(fmt):break
        c=fmt[i];i+=1
        if c in 'dHMS':
            div={'d':86400,'H':3600,'M':60,'S':1}[c]
            value=truncdiv(n,div)
            if not extended and c!='d':
                modulus=24 if c=='H' else 60
                value-=truncdiv(value,modulus)*modulus
            out+=f'{value:02d}' if pad else str(value)
        elif c=='%':out+='%'
        else:out+='?'
    return out

def format_item(item,fmt,notes,day=None,start=None,now=None):
    start=start or item.start
    if now is None:now=int(time.time())
    if day is None and start is not None:day=start.date()
    def time_default(value,is_end=False):
        lo,hi=epoch(day),epoch(day+DAY)
        if (not is_end and value<lo) or (is_end and value>hi):return '..:..'
        return stamp(value).strftime('%H:%M')
    def spec(name,form=None):
        if name=='raw':return item.raw()+'\n'
        if name=='hash':return item.hash()
        if name=='m':return item.message
        if name=='n':return item.note if item.note is not None else '(null)'
        if name=='N':
            try:
                content=read_text(os.path.join(notes,item.note)) if item.note else None
            except OSError:content=None
            if content is None:return '\tNo note file found\n'
            return ''.join('\t'+line+'\n' for line in content.splitlines())
        if name=='p' and item.kind=='todo':return str(item.priority)
        if item.kind!='apt':return '?'
        s=epoch(start);e=s+item.duration
        if name=='s':return str(s)
        if name=='e':return str(e)
        if name=='S':return time_default(s)
        if name=='E':return time_default(e,True)
        if name=='d':return str(item.duration)
        if name=='r':return duration_format(s-now,'default')
        if name in ('start','end'):
            value=s if name=='start' else e
            if form=='epoch':return str(value)
            if not form or form=='default':return time_default(value,name=='end')
            return stamp(value).strftime(form)
        if name in ('duration','remaining'):
            value=item.duration if name=='duration' else s-now
            if not form:
                return str(value) if name=='duration' else duration_format(value,'default')
            return duration_format(value,form)
        return '?'
    out='';i=0
    escapes={'n':'\n','t':'\t','a':'\a','b':'\b','f':'\f','r':'\r','v':'\v','0':'\0','\\':'\\'}
    while i<len(fmt):
        c=fmt[i];i+=1
        if c=='\\':
            if i<len(fmt):out+=escapes.get(fmt[i],'');i+=1
        elif c=='%':
            if i==len(fmt):break
            c=fmt[i];i+=1
            if c=='%':out+='%'
            elif c=='(':
                k=fmt.find(')',i)
                if k<0:break
                name,sep,form=fmt[i:k].partition(':');i=k+1
                out+=spec(name,form if sep else None)
            else:out+=spec(c)
        else:out+=c
    return out
