@dataclass
class Item:
    kind: str
    message: str = ''
    start: object = None
    duration: int = 0
    priority: int = 0
    completed: bool = False
    ident: int = 1
    note: object = None
    flagged: bool = False
    repeat: object = None

    @property
    def type(self):
        return ('recur-' if self.repeat else '') + self.kind

    @property
    def end(self):
        if self.kind == 'event':
            return self.start + timedelta(seconds=86399)
        return stamp(epoch(self.start) + self.duration)

    def raw(self):
        n = '>' + self.note + ' ' if self.note is not None else ''
        if self.kind == 'todo':
            return '[' + ('-' if self.completed else '') + str(self.priority) + ']' + n + ('' if n else ' ') + self.message
        if self.kind == 'event':
            return native_date(self.start) + ' [' + str(self.ident) + '] ' + (self.repeat.raw() + ' ' if self.repeat else '') + n + self.message
        return native_datetime(self.start) + ' -> ' + native_datetime(self.end) + (' ' + self.repeat.raw() + ' ' if self.repeat else '') + n + ('!' if self.flagged else '|') + self.message

    def hash(self):
        return digest(self.raw())

    def sortkey(self):
        if self.kind == 'todo':
            return (int(self.completed), self.priority if self.priority else 10, self.message)
        if self.kind == 'event':
            return (self.start, self.message)
        return (self.start, not self.flagged, self.message)

    def occurrences(self, d):
        if self.kind == 'todo':
            return []
        if self.kind == 'event':
            if (self.repeat and self.repeat.matches(self.start,d)) or (not self.repeat and self.start.date() == d):
                return [(self, midnight(d))]
            return []
        lo, hi = epoch(d), epoch(d + DAY)
        if not self.repeat:
            s = epoch(self.start)
            return [(self,self.start)] if s < hi and (s + self.duration > lo or s == lo) else []
        results = []
        # A long appointment may overlap the day from an earlier repetition.
        count = max(1, self.duration//86400+2)
        begin = max(self.start.date(), d-timedelta(days=count))
        while begin <= d:
            if self.repeat.matches(self.start,begin):
                st = datetime.combine(begin, self.start.time())
                s = epoch(st)
                if s < hi and (s + self.duration > lo or s == lo):
                    results.append((self,st))
            begin += DAY
        return results

NDATE = r'([+-]?\d+)\s*/\s*([+-]?\d+)\s*/\s*([+-]?\d+)'

def parse_native_date(s):
    m = re.fullmatch(NDATE,s.strip())
    if not m:
        raise ValueError('syntax error in the item date')
    try:
