    except (ValueError, OverflowError):
        raise ValueError('date error in event')

def parse_repeat(s):
    m = re.match(r'\s*(\d+)([DWMY])',s)
    if not m:
        raise ValueError('syntax error in the repetition')
    r = Repeat(int(m[1]),m[2]); tail=s[m.end():].strip()
    if tail.startswith('->'):
