        if not m:
            raise ValueError('syntax error in the repetition')
        r.until=date(int(m[3]),int(m[1]),int(m[2])); tail=tail[m.end():]
    while tail.strip():
        tail=tail.lstrip()
        m=re.match(r'([wmd])([+-]?\d+)',tail)
        if m:
