def read_note_fields(item,notes):
    if item.note is None:return []
    try:text=read_text(os.path.join(notes,item.note))
    except OSError:return []
    result=[]
    if '-- \n' in text:
        description,extra=text.split('-- \n',1)
    else:description=text;extra=''
    if description:
        result.append(('DESCRIPTION',description[:-1] if description.endswith('\n') else description))
    extra_lines=extra.splitlines();current=None;value='';seen=set()
    for s in extra_lines+['']:
        if current and s.startswith('    '):value+='\n'+s[4:];continue
        if current and current not in seen:
            result.append((current,value));seen.add(current)
        current=None
        for key in ('Location','Comment'):
            if s.startswith(key+': '):current=key.upper();value=s[len(key)+2:];break
    return result

def ical_date(d):
    return f'{d.year:04d}{d.month:02d}{d.day:02d}'

def ical_datetime(d):
    return ical_date(d)+f'T{d.hour:02d}{d.minute:02d}{d.second:02d}'

def rrule_lines(it):
    r=it.repeat
    if not r:return []
    s='RRULE:FREQ='+FREQUENCIES.get(r.unit,'DAILY')
    if r.interval>1:s+=';INTERVAL='+str(r.interval)
    if r.until:
        s+=';UNTIL='+ical_date(r.until)
        if it.kind=='apt':s+='T'+it.start.strftime('%H%M%S')
    if r.months:s+=';BYMONTH='+','.join(map(str,r.months))
    if r.weekdays:
        days=[]
        for w in r.weekdays:
            wd=abs(w)%7;ordinal=abs(w)//7
            days.append(('+' if w>0 else '-')+str(ordinal)+WEEKDAYS[wd] if ordinal else WEEKDAYS[wd])
        s+=';BYDAY='+','.join(days)
    if r.monthdays:s+=';BYMONTHDAY='+','.join(map(str,r.monthdays))
    out=[s]
    if r.exceptions:
        suffix=it.start.strftime('%H%M%S') if it.kind=='apt' else '000000'
        out.append(('EXDATE:' if it.kind=='apt' else 'EXDATE;VALUE=DATE:')+','.join(ical_date(d)+'T'+suffix for d in sorted(r.exceptions)))
    return out

def export_ical(items,opts,notes):
    lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//calcurse//NONSGML v4.8.2//EN']
    for it in ordered(items,EXPORT_ORDER):
        component='VTODO' if it.kind=='todo' else 'VEVENT'
        lines.append('BEGIN:'+component)
        if opts.exportuid:lines.append('UID:'+it.hash())
        if it.kind=='todo':lines.append('PRIORITY:'+str(it.priority))
        elif it.kind=='event':lines.append('DTSTART;VALUE=DATE:'+ical_date(it.start))
        else:
            lines.append('DTSTART:'+ical_datetime(it.start))
            if it.duration:
                d,rem=divmod(it.duration,86400);h,rem=divmod(rem,3600);m,s=divmod(rem,60)
                lines.append(f'DURATION:P{d}DT{h}H{m}M{s}S')
        lines.extend(rrule_lines(it))
        lines.append('SUMMARY:'+encode_text(it.message))
        for name,text in read_note_fields(it,notes):lines.append(name+':'+encode_text(text))
        if it.kind=='todo' and it.completed:lines.append('STATUS:COMPLETED')
        if it.kind=='apt' and it.flagged:
            lines.extend(['BEGIN:VALARM','TRIGGER:-PT'+str(atoi(opts.config.get('notification.warning','300')))+'S','ACTION:DISPLAY','END:VALARM'])
