def export_pcal(items,opts):
    def line(it,rec=False):
        when=it.start.strftime('%b %d')
        if rec:
            r=it.repeat
            if r.until:return ''
            if r.interval!=1:return ''
            if r.unit=='D':when='all day on_or_after '+when
            elif r.unit=='W':when='all '+it.start.strftime('%A')+' on_or_after '+when
            elif r.unit=='M':when='day '+str(it.start.day)+' of all'
            elif r.unit=='Y':pass
        message=it.message
        if it.kind=='apt':message='('+it.start.strftime('%H:%M')+' -> '+it.end.strftime('%H:%M')+') '+message
        return when+'  '+message+'\n'
    output=PCAL_HEADER
    for kind,head in [('recur-event',''),('event',PCAL_EVENTS),('recur-apt',PCAL_RECUR_APT),('apt',PCAL_APTS),('todo',PCAL_TODOS)]:
        output+=head
        for it in sorted([it for it in items if it.type==kind],key=lambda i:i.sortkey()):
            if kind=='todo':
                if not it.completed:output+=f'note all  {it.priority}. {it.message}\n'
            else:output+=line(it,kind.startswith('recur-'))
    return output+'\n'
