            else:
                pairs=[('?','Help','q','Quit'),('s','Save','R','Reload'),('TAB','Chg Win','...','Prev Win'),('^N','Nxt View','^P','Prv View'),('i','Import','x','Export'),('a','Add Item','o','OtherCmd')]
            if self.other:
                pairs=[('g','GoTo','^G','Today'),('!','Flag','r','Repeat'),('v','View','e','Edit Itm'),('c','Copy','p','Paste'),('n','EditNote','>','ViewNote'),('t','Nxt Day','o','OtherCmd')]
            width=self.w//6
            for n,(a,b,c,d) in enumerate(pairs):
                self.put(self.h-2,n*width,f'{a:>3} {b}')
