    def edit(self,item):
        if item is None:return
        if item.kind=='todo':
            val=self.ask('Enter the new TODO description:',item.message)
            if val is not None:item.message=val
        elif item.kind=='event':
            val=self.ask('Enter description:',item.message)
            if val is not None:item.message=val
        else:
            if item.repeat:
                which=self.choose('Edit: (1) Start time, (2) End time, (3) Description, (4) Repetition, (5) Move?','12345')
            else:which=self.choose('Edit: (1) Start time, (2) End time, (3) Description, (4) Move?','1234')
            if which=='3':
                val=self.ask('Enter description:',item.message)
                if val is not None:item.message=val
            elif which=='4' and item.repeat:self.repeat(item,True)
            elif which in ('1','2'):
                val=self.ask('Enter start time:' if which=='1' else 'Enter end time:',item.start.strftime('%H:%M') if which=='1' else item.end.strftime('%H:%M'))
