            which=self.choose('This item is recurrent. Delete (s)elected occurrence or (a)ll occurrences?','sa')
            if which=='s':item.repeat.exceptions.append(self.day);self.changed=True
            elif which=='a':self.items.remove(item);self.changed=True
        elif self.config.get('general.confirmdelete','yes')=='no' or self.choose('Do you really want to delete this item?','yn')=='y':
            self.items.remove(item);self.changed=True

    def note(self,item):
