            elif c in ('?','@'):self.tell('calcurse 4.8.2 -- text-based organizer. Press any key to return.')


def run_interactive(items,opts,data,conf,apts,todos):
    keyfile=os.path.join(conf,'keys')
    if not opts.readonly and not os.path.exists(keyfile):write_text(keyfile,KEYS_HEADER+KEY_BINDINGS)
    pidfile=os.path.join(data,'.calcurse.pid')
    try:write_text(pidfile,str(os.getpid())+'\n')
    except OSError:pass
    term=os.environ.get('TERM','unknown')
    if not term or term=='unknown':
        sys.stderr.write('Error opening terminal: unknown.\n');return 1
    try:
        curses.wrapper(lambda scr:Interface(scr,items,opts,data,conf,apts,todos).loop())
    except (curses.error,KeyboardInterrupt):return 1
    finally:
        try:os.unlink(pidfile)
        except OSError:pass
    return 0
