def start_daemon(data,apts,config):
    pidfile=os.path.join(data,'.daemon.pid')
    logpath=os.path.join(data,'daemon.log')
    logging=config.get('daemon.log','no')=='yes'
    def log(message):
        if logging:
            try:
                with open(logpath,'a') as f:f.write(message+'\n');f.flush()
            except OSError:pass
    def clock():return time.strftime('%a %b %d %H:%M:%S %Y')
    try:old=atoi(read_text(pidfile))
    except OSError:old=0
    if old>1 and old!=os.getpid():
        try:os.kill(old,signal.SIGINT);time.sleep(.05)
        except OSError:pass
    pid=os.fork()
    if pid:return
    try:
        os.setsid()
        null=os.open(os.devnull,os.O_RDWR)
        for fd in (0,1,2):os.dup2(null,fd)
        if null>2:os.close(null)
        def terminate(signum,frame=None):
            log('terminated at '+clock()+' with signal '+str(signum))
            try:
                if atoi(read_text(pidfile))==os.getpid():os.unlink(pidfile)
            except OSError:pass
            os._exit(0)
        signal.signal(signal.SIGTERM,terminate)
        signal.signal(signal.SIGINT,terminate)
        signal.signal(signal.SIGHUP,terminate)
        try:read_text(apts)
        except OSError as e:
            log('Could not access "'+apts+'": '+e.strerror)
            terminate(2)
        write_text(pidfile,str(os.getpid())+'\n')
        log('started at '+clock())
        sent=set()
        while True:
            now=int(time.time());items=[]
            try:
                for line in read_text(apts).splitlines():items.append(parse_item(line,'apt'))
            except (OSError,ValueError,CalendarError):pass
            warning=atoi(config.get('notification.warning','300'))
            for it in items:
                if it.kind!='apt':continue
                for d in [date.today(),date.today()+DAY]:
                    for item,st in it.occurrences(d):
                        at=epoch(st);key=(it.hash(),at)
                        if key not in sent and now<=at<=now+warning:
                            if config.get('notification.notifyall','flagged-only') in ('all','unflagged-only') or it.flagged:
                                command=config.get('notification.command','')
                                if command:
                                    try:subprocess.Popen(command,shell=True,stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
                                    except OSError:pass
                                sent.add(key)
            log('sleeping at '+clock()+' for 60 seconds')
            time.sleep(60)
    except BaseException:
        os._exit(1)
